class Solution:
    def maximumWhiteTiles(self, tiles, carpetLen):
        tiles.sort()
        n = len(tiles)
        pre = [0] * (n + 1)
        for i, (l, r) in enumerate(tiles):
            pre[i + 1] = pre[i] + r - l + 1
        ans = j = 0
        for i in range(n):
            while j < n and tiles[j][1] - tiles[i][0] + 1 <= carpetLen:
                j += 1
            cov = pre[j] - pre[i]
            if j < n:
                cov += max(0, tiles[i][0] + carpetLen - tiles[j][0])
            ans = max(ans, cov)
        return ans

