class Solution {
    public int maximumWhiteTiles(int[][] tiles, int carpetLen) {
        Arrays.sort(tiles, (a, b) -> Integer.compare(a[0], b[0]));
        int n = tiles.length;
        long[] pre = new long[n + 1];
        int[] rights = new int[n];
        for (int i = 0; i < n; i++) {
            pre[i + 1] = pre[i] + tiles[i][1] - tiles[i][0] + 1;
            rights[i] = tiles[i][1];
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int limit = tiles[i][0] + carpetLen - 1;
            int j = upperBound(rights, limit);
            long cov = pre[j] - pre[i];
            if (j < n) cov += Math.max(0, limit - tiles[j][0] + 1);
            ans = Math.max(ans, cov);
        }
        return (int) ans;
    }
    private int upperBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= x) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

